# -*- coding: utf-8 -*-
from html import escape
from catalog import SOURCES
PAGES=['index','map','standards','ecc','sm2-sign','sm2-encrypt','sm2-exchange','ecc-compare','sm3','hash-compare','sm4','aes-compare','modes','sm9','zuc','protocols','engineering','practice','labs','tools','sources']
NAV={'en':['Overview','Algorithm map','Standards','ECC foundations','SM2 signatures','SM2 encryption','SM2 exchange','NIST ECC comparison','SM3','SHA-2 / SHA-3 comparison','SM4','AES comparison','Modes & MACs','SM9','ZUC','Protocols','Engineering','Practice','Labs','Tools','Sources'],'zh':['总览','算法全景','标准体系','ECC 基础','SM2 签名','SM2 加密','SM2 密钥交换','NIST ECC 对比','SM3','SHA-2 / SHA-3 对比','SM4','AES 对比','模式与 MAC','SM9','ZUC','协议','实现工程','实践','互动实验','工具','资料']}
DESCRIPTIONS=[('SM1/2/3/4/7/9, ZUC and the limits of public specifications','SM1/2/3/4/7/9、ZUC 与公开规范边界'),('Algorithm standards, usage profiles, protocol standards and version status','算法标准、使用规范、协议标准及版本状态'),('Field arithmetic, scalar arithmetic, point validation and encodings','有限域、标量、点验证及编码'),('ZA, signing and verification, nonce failures and signature encodings','ZA、签名验签、Nonce 风险与签名编码'),('KDF, C1/C2/C3, integrity checks and ciphertext encodings','KDF、C1/C2/C3、完整性检查及密文编码'),('Static and ephemeral keys, identity binding and key confirmation','静态与临时密钥、身份绑定及密钥确认'),('Exact SM2 / P-256 parameters and ECDSA / ECDH differences','SM2 / P-256 精确参数及 ECDSA / ECDH 差异'),('Padding, 68-word expansion, 64 rounds and XOR feed-forward','填充、68 字扩展、64 轮与异或前馈'),('SHA-256/512 compression versus Keccak sponge and SHAKE','SHA-256/512 压缩与 Keccak 海绵 / SHAKE'),('S-box, data/key transforms, 32 rounds and reversed output','S 盒、数据 / 密钥变换、32 轮及反序输出'),('Word-based SM4 versus byte-based AES-128/192/256','按字的 SM4 与按字节的 AES-128/192/256'),('ECB/CBC/CTR, authenticated encryption, HMAC and key management','ECB/CBC/CTR、认证加密、HMAC 与密钥管理'),('Identity-based cryptography, bilinear pairings and KGC trust','标识密码、双线性对及 KGC 信任'),('Stream-cipher structure, EEA3/EIA3 and distinct 256-bit profiles','流密码结构、EEA3/EIA3 与独立 256 位配置'),('TLCP, TLS 1.3 SM suites, certificates and interoperability','TLCP、TLS 1.3 国密套件、证书及互操作'),('Constant-time design, randomness, acceleration and validation','恒定时间设计、随机数、加速及验证'),('Downloadable readable reference code and independent checks','可下载的可读参考实现与独立验证'),('Hash traces, SM4/AES block traces and curve inspection','杂凑轨迹、SM4/AES 分组轨迹及曲线检查'),('Search primary standards and original implementations','搜索一手标准与原始实现'),('Source scope, draft status and accessible reading routes','来源范围、草案状态及阅读入口')]

def chapter(page,lang):
    t=lambda en,zh:zh if lang=='zh' else en
    p=lambda *items:''.join('<p>'+x+'</p>' for x in items)
    code=lambda text:'<pre><code>'+escape(text)+'</code></pre>'
    def table(headers,rows):
        return '<div class="table-wrap" tabindex="0"><table><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
    rows=[]
    def add(ident,en,zh,inten,intzh,body,refs,viz=''):
        if isinstance(refs,str): refs=(refs,)
        rows.append((ident,t(en,zh),t(inten,intzh),body,refs,viz))
    if page=='map':
        add('roles','Start with the function, not the number','先看功能，再看编号','GM names cover several different cryptographic jobs.','国密名称覆盖不同密码功能。',table([t('Family','算法族'),t('Role','功能'),t('Public learning scope','公开学习范围')],[('SM1 / SM7',t('Symmetric block ciphers','对称分组密码'),t('Names and deployment contexts are public; full round specifications are not part of the open materials used here','名称及应用场景公开，本网站使用的开放资料不包含完整逐轮规范')),('SM2',t('ECC signatures, encryption and key exchange','ECC 签名、加密与密钥交换'),t('Public arithmetic and protocols; each function needs its own API','公开算术及协议，各功能需要独立 API')),('SM3',t('256-bit cryptographic hash','256 位密码杂凑'),t('Public compression function; no secret key in an ordinary hash','公开压缩函数，普通杂凑没有秘密密钥')),('SM4',t('128-bit-key / 128-bit-block cipher','128 位密钥 / 128 位分组密码'),t('Public S-box, key schedule and 32-round core','公开 S 盒、密钥计划及 32 轮核心')),('SM9',t('Identity-based public-key cryptography','基于标识的公钥密码'),t('Pairing-based signatures, exchange, encapsulation and encryption','基于双线性对的签名、交换、封装及加密')),('ZUC',t('Stream-cipher family','序列密码族'),t('Keystream generation and separate confidentiality/integrity profiles','密钥流生成及独立机密性 / 完整性配置'))])+p(t('These are the principal named families in this atlas. “All GM algorithms” is not a finite consecutive SM1–SM9 list: industry standards also define constructions, interfaces and protocols. A number gap does not justify inventing an SM5, SM6 or SM8 specification. Legacy or vendor labels need an exact primary specification before comparison.','这里列出主要命名算法族。“所有国密算法”并不是连续 SM1–SM9 的有限清单；行业标准还定义构造、接口和协议。编号缺口不能成为编造 SM5、SM6、SM8 规范的依据。历史或厂商名称须先定位精确一手规范再比较。')),('gm-index','family','closed'),'map')
        add('closed','Treat limited disclosure as a real boundary','承认公开细节的边界','Do not fill a missing specification with a guess.','不能用猜测填补缺少的规范。',p(t('SM1 and SM7 are symmetric algorithm names encountered in cryptographic products; SM7 appears in tag/reader and identification contexts. Public descriptions do not supply enough detail to reconstruct and independently test the full core. This guide therefore explains their category and application boundary without inventing round counts, S-boxes or a universal key-size table.','SM1 与 SM7 是密码产品中使用的对称算法名称；SM7 可见于标签 / 读写器与身份鉴别场景。公开描述不足以重建并独立测试完整核心。因此本网站解释类别及应用边界，不编造轮数、S 盒或通用密钥长度表。'),t('A closed implementation’s assurance must be evaluated through its documented interface, tested behavior, product scope and applicable assurance evidence. Secrecy of the specification alone is not a security proof. An open-source SM2/3/4 library cannot silently substitute for an SM1/7 device function.','非公开实现应根据接口文档、测试行为、产品范围及相应保障证据评估。规范不公开本身不是安全证明。开源 SM2/3/4 库不能悄悄替代 SM1/7 设备功能。')),('closed','family'))
        add('layers','An algorithm, a mode and a protocol are separate layers','算法、模式与协议是不同层次','SM4, SM4-GCM and a TLS suite are different objects.','SM4、SM4-GCM 与 TLS 套件是不同对象。',p(t('The primitive gives a precisely defined transformation. A mode or construction adds nonce handling, authentication or key derivation. A protocol chooses identities, keys, negotiation and message order. A certified module or product adds a further assurance scope. Compare corresponding layers: SM2 signature ↔ ECDSA, SM3 ↔ SHA-256 / SHA3-256, SM4 ↔ AES-128, SM4-GCM ↔ AES-GCM.','原语定义精确变换，模式或构造加入 Nonce、认证或密钥派生，协议选择身份、密钥、协商及消息顺序。认证模块或产品又有独立保障范围。应比较对应层次：SM2 签名 ↔ ECDSA，SM3 ↔ SHA-256 / SHA3-256，SM4 ↔ AES-128，SM4-GCM ↔ AES-GCM。'),t('SM9 is not another SM2 curve, and ZUC is not a block mode of SM4. Both deserve separate trust and state models.','SM9 不是另一条 SM2 曲线，ZUC 不是 SM4 的分组模式；二者都需要独立信任及状态模型。')),('tls-sm','aes','gb-sm9','zuc'))
    elif page=='standards':
        add('hierarchy','Locate the exact standard and layer','定位精确标准与层次','GM/T, GB/T and an RFC do not mean the same thing.','GM/T、GB/T 与 RFC 不是同一种标识。',table([t('Reference','参考'),t('What it covers','内容')],[('GB/T 32918.1–.5',t('SM2 foundations; signatures; key exchange; public-key encryption; parameters','SM2 总则、签名、密钥交换、公钥加密、参数')),('GB/T 32905-2016 / 32907-2016',t('SM3 / SM4 algorithm cores','SM3 / SM4 算法核心')),('GB/T 38635.1–.2-2020',t('SM9 foundations and algorithms','SM9 总则及算法')),('GM/T 0001 / 0002 / 0003 / 0004',t('ZUC / SM4 / SM2 / SM3 industry algorithm families','ZUC / SM4 / SM2 / SM3 行业算法族')),('GM/T 0009-2023; GB/T 35276-2017',t('SM2 usage rules, not a replacement signature formula','SM2 使用规范，不是替代签名公式')),('GB/T 35275; GM/T 0010',t('SM2 message representations and structures','SM2 消息表示及结构')),('GB/T 38636-2020; RFC 8998',t('TLCP; a distinct SM profile for TLS 1.3','TLCP；独立的 TLS 1.3 国密配置'))])+p(t('GB/T and GM/T use recommended-standard designations. Whether a particular system must use a standard depends on its actual requirements; a learning atlas does not make that determination. Read the issuer’s version/status record rather than inferring legal obligations from an algorithm name.','GB/T 与 GM/T 是推荐性标准标识。具体系统是否必须使用某标准依赖实际要求，学习网站不作该裁定。应阅读发布者版本 / 状态记录，不从算法名推导法律义务。')),('gm-index','gb-sm2','gb-sm3','gb-sm4','gb-sm9','gm-usage'),'standards')
        add('versions','Distinguish current, future and historical material','区分现行、未来与历史材料','Review date: 1 October 2026.','复核日期：2026 年 10 月 1 日。',p(t('The official SM2 list shows GB/T 35275-2026, published 30 April 2026, with an implementation date of 1 November 2026. As of this review it is a forthcoming message-format standard, not an already-effective replacement. It does not by itself change the SM2 curve or signing equations. GM/T 0009-2023 is a different, updated industry usage document.','官方 SM2 清单显示 GB/T 35275-2026 于 2026 年 4 月 30 日发布、2026 年 11 月 1 日实施；在本次复核时是即将实施的消息格式标准，并非已生效替代。它本身不改变 SM2 曲线或签名公式。GM/T 0009-2023 是另一份已更新的行业使用文档。'),t('The English SM2, SM3 and SM4 Internet-Drafts linked here are expired explanatory drafts, not published RFC algorithm standards. They are useful for formulas and historical vectors but must be cross-checked with GB/GM texts. RFC 8998 is a published Informational RFC on an Independent Submission stream, with a narrow TLS 1.3 scope.','这里链接的 SM2、SM3、SM4 英文 Internet-Draft 是过期解释性草案，不是已发布 RFC 算法标准。它们便于阅读公式及历史向量，但应与 GB/GM 文本对照。RFC 8998 是独立提交流上的 Informational RFC，范围限于 TLS 1.3 配置。')),('gb-sm2','gm-usage','sm2-draft','sm3-draft','sm4-draft','tls-sm'))
        add('reading','Keep three kinds of evidence','保留三种证据','A correct output, interoperable bytes and assurance scope answer different questions.','正确输出、互操作字节及保障范围回答不同问题。',p(t('Use a normative standard to identify required behavior; an implementor’s code and test vectors to inspect execution; a protocol profile to identify the wire representation and identity context. For product assurance, locate evidence tied to that exact module/build and scope. A NIST comparison is an engineering comparison, not recognition of GM algorithms as FIPS-approved algorithms.','用规范标准确认要求，用实现源码及向量检查执行，用协议配置确认线上表示和身份上下文。产品保障须定位精确模块 / 构建及范围的证据。与 NIST 对比是工程比较，不意味着国密算法属于 FIPS 批准算法。')),('nist-dss','gmssl','tls-sm'))
    elif page=='ecc':
        add('domains','Use mod p for coordinates, mod n for scalars','坐标用 mod p，标量用 mod n','Mixing the two moduli produces plausible-looking but wrong code.','混用两个模数会产生看似合理的错误代码。',code('Curve: y² = x³ + ax + b  (mod p)\nDomain: (p, a, b, G, n, h)\nPublic key: P = [d]G\nPoint addition / doubling: arithmetic in Fp\nSignature scalar arithmetic: mod n')+p(t('p defines the prime field; n is the prime order of the chosen base-point subgroup; h is the cofactor. They are different integers even when both occupy 32 bytes. The point at infinity is the group identity, not coordinate (0,0). curveSM2 and NIST P-256 are short-Weierstrass prime-field curves with a = −3 mod p and h = 1, but p, b, G and n are different.','p 定义素域，n 是所选基点子群的素数阶，h 是余因子；即使都占 32 字节，p 与 n 仍是不同整数。无穷远点是群单位元，不是坐标 (0,0)。curveSM2 与 NIST P-256 都是短 Weierstrass 素域曲线，a = −3 mod p、h = 1，但 p、b、G、n 不同。')),('nist-curves','tls-sm'),'ecc')
        add('points','Point arithmetic must handle exceptional cases','点运算必须处理特殊情形','An affine formula is readable, but is not a fast or constant-time implementation.','仿射公式易读，但不是快速或恒定时间实现。',code('P=(x1,y1), Q=(x2,y2)\nP≠Q: λ=(y2−y1)/(x2−x1) mod p\nP=Q: λ=(3x1²+a)/(2y1) mod p\nx3=λ²−x1−x2 mod p\ny3=λ(x1−x3)−y1 mod p\nP + (−P) = infinity')+p(t('Modular division means inversion, not floating-point division. Real software commonly uses projective coordinates to avoid an inverse per addition, plus scalar-multiplication strategies chosen for the threat model. Secret-dependent double-and-add branches, table indices, and variable-time inversions can leak keys. “It returns the right point” is only a functional check.','模除法指求逆，不是浮点除法。真实软件通常使用投影坐标避免每次加法求逆，并按威胁模型选择标量乘策略。秘密相关的倍点加分支、表索引和变时求逆会泄露密钥。“返回正确点”只是功能检查。')),('nist-curves','nist-kex'))
        add('validation','Validate both the point and its encoding','验证点与编码','Never decode an attacker-supplied point by assuming it is valid.','不能假定攻击者提供的点有效。',p(t('Check coordinate bounds, the curve equation, non-infinity and the subgroup condition appropriate to the domain and protocol. An uncompressed public point commonly uses 04 || x || y, with 32-byte big-endian coordinates on these curves. That is 65 bytes, not a universal public-key file format: DER SubjectPublicKeyInfo also carries algorithm identifiers.','应检查坐标范围、曲线方程、非无穷远，以及域和协议要求的子群条件。这些曲线的非压缩点通常为 04 || x || y，坐标各 32 字节大端，共 65 字节；它不是通用公钥文件格式，DER SubjectPublicKeyInfo 还携带算法标识。'),t('A 256-bit ECC private scalar is not a 256-bit security claim. Generic discrete-log work on a suitable 256-bit prime-order group is roughly 2¹²⁸ classical operations. Parameter correctness, protocol assumptions, implementation leakage and future quantum attacks are separate questions.','256 位 ECC 私钥标量不意味着 256 位安全强度。适当 256 位素数阶群的通用离散对数攻击约需 2¹²⁸ 次经典运算。参数正确性、协议假设、实现泄漏及未来量子攻击是独立问题。')),('nist-kex','strength','pqc'))
    elif page=='sm2-sign':
        add('za','ZA binds identity, domain and public key','ZA 绑定身份、域参数与公钥','The digest is not just SM3(message).','摘要不是简单 SM3(message)。',code('ZA = SM3(ENTLA || IDA || a || b || xG || yG || xA || yA)\ne  = integer(SM3(ZA || M))\nENTLA = 16-bit big-endian bit length of IDA\nAll field elements above: fixed-width big-endian octets')+p(t('IDA is a protocol-defined byte string, not an implicit operating-system username. For a 16-byte ASCII ID, ENTL is 128 bits: 00 80, not 00 10. For UTF-8, count encoded bytes and then multiply by eight. Changing the ID, public key or domain changes ZA; signer and verifier must use the same context. A default ID from one library is not universally mandated for every protocol.','IDA 是协议定义的字节串，不是隐含操作系统用户名。16 字节 ASCII ID 的 ENTL 是 128 位，即 00 80，不是 00 10。UTF-8 需先数编码字节再乘八。改变 ID、公钥或域参数都会改变 ZA；双方须使用相同上下文。某库默认 ID 不适用于所有协议。')),('sm2-draft','openssl-sm2','tls-sm'),'sm2-sign')
        add('equations','Read the signing and verification equations together','一起阅读签名与验签公式','SM2 signatures are not ECDSA signatures on a renamed curve.','SM2 签名不是改名曲线上的 ECDSA。',code('Sign, d∈[1,n−2], fresh k∈[1,n−1]:\n(x1,y1) = [k]G\nr = (e + x1) mod n\nretry if r=0 or r+k=n\ns = ((1+d)⁻¹ × (k−r d)) mod n\nretry if s=0\n\nVerify, first check r,s∈[1,n−1] and valid PA:\nt = (r+s) mod n; reject t=0\n(x1′,y1′) = [s]G + [t]PA; reject infinity\naccept iff (e′+x1′) mod n = r')+p(t('The signing key excludes n−1 because (1+d) would have no inverse mod n. The verification equation works because s+(r+s)d = k mod n. A public-key multiplication routine is shared ECC machinery; the surrounding signature equation remains distinct.','签名私钥排除 n−1，因为 1+d 在 mod n 下无法求逆。验签成立的关系是 s+(r+s)d = k mod n。公钥乘法例程可以共用 ECC 机制，外层签名等式仍不同。')),('sm2-draft','nist-dss'))
        add('nonce','Nonce reuse exposes a private scalar','Nonce 重用会暴露私钥标量','Secure randomness is part of the algorithm’s implementation.','安全随机数是算法实现的一部分。',code('For reused k and two valid SM2 signatures:\ns1 + (s1+r1)d = k mod n\ns2 + (s2+r2)d = k mod n\nd = (s2−s1) / (s1+r1−s2−r2) mod n\nwhen the denominator is invertible')+p(t('Nonce bias, partial leakage and a side channel can also be dangerous without exact reuse. Do not transplant ECDSA’s deterministic-nonce procedure without a specified, analyzed SM2 construction. Fixed nonces in the downloadable tests are public synthetic values to reproduce equations, never a deployment recommendation.','Nonce 偏差、部分泄漏和侧信道也可能危险，并非只有完全重用。不能在缺少明确、经分析的 SM2 构造时直接移植 ECDSA 确定性 Nonce 方法。下载测试中的固定 Nonce 是用于复现等式的公开合成值，不是部署建议。'),t('Signatures are a pair (r,s), often encoded either as fixed 32+32-byte values or a DER SEQUENCE of two INTEGERs. DER INTEGER is signed: a leading 00 may be needed, so DER length is variable. Identity/digest mismatch, double hashing, key type confusion and raw/DER confusion cause common interoperability failures.','签名是 (r,s) 对，常见编码为固定 32+32 字节或包含两个 INTEGER 的 DER SEQUENCE。DER INTEGER 为有符号数，可能需要前导 00，因此长度可变。身份 / 摘要不匹配、双重哈希、密钥类型混淆和 raw / DER 混淆是常见互操作问题。')),('openssl-sm2','sm2-draft','x509'))
    elif page=='sm2-encrypt':
        add('pieces','C1, C2 and C3 do different jobs','C1、C2、C3 功能不同','Encryption combines ephemeral ECC, a KDF and an integrity digest.','加密组合临时 ECC、KDF 与完整性摘要。',code('Validate recipient public key PB\nfresh k∈[1,n−1]; C1=[k]G\n(x2,y2)=[k]PB\nt=KDF(x2 || y2, bit_length(M)); retry if t is all zero\nC2=M XOR t\nC3=SM3(x2 || M || y2)\nTeaching wire profile: uncompressed C1 || C3 || C2')+p(t('C1 lets the receiver reconstruct the shared point using its private scalar. C2 carries encrypted bytes. C3 checks the recovered plaintext and shared coordinates. SM2 encryption does not use ZA in the way SM2 signatures do; adding an ID to a signature API does not configure encryption authentication. Encryption to a public key also does not prove who the sender is.','C1 让接收方以私钥重建共享点，C2 携带加密字节，C3 检查恢复明文及共享坐标。SM2 加密不以 SM2 签名的方式使用 ZA；给签名 API 设置 ID 不会配置加密认证。向公钥加密也不能证明发送者身份。')),('sm2-draft','gb-sm2'),'sm2-encrypt')
        add('receive','Do not release plaintext before C3 verification','验证 C3 前不能释放明文','Decryption checks structure, point validity and recovered data.','解密检查结构、点有效性与恢复数据。',code('Validate C1 and protocol-required cofactor/subgroup conditions\n(x2,y2)=[dB]C1\nt=KDF(x2 || y2, bit_length(C2)); reject all-zero t\nM=C2 XOR t\nu=SM3(x2 || M || y2)\nCompare u with C3; only then return M\n\nKDF(Z,klen): SM3(Z || ct), ct=00000001,00000002,…\nConcatenate and truncate to klen bits')+p(t('The KDF counter is four-byte big-endian and starts at one. Field values use fixed widths; dropping leading zeros changes every result. The tutorial API takes lengths in bytes and supports byte-aligned messages only. A production protocol must define bounds, error handling and rejection timing to avoid creating a decryption oracle.','KDF 计数器为四字节大端，从一开始。域元素使用固定宽度，删除前导零会改变所有结果。教程 API 使用字节长度，仅支持字节对齐消息。生产协议应定义边界、错误处理及拒绝时间，避免形成解密预言机。')),('sm2-draft','gm-usage'))
        add('formats','Raw concatenation and ASN.1 are not interchangeable','原始拼接与 ASN.1 不能互换','C1C2C3 and C1C3C2 can both appear in historical libraries.','历史库中可见 C1C2C3 与 C1C3C2。',p(t('Some older descriptions and APIs output C1C2C3; modern profiles and libraries may select C1C3C2 or an ASN.1 structure. This project explicitly uses 04||x1||y1||C3||C2. Its OpenSSL test converts to a DER structure containing x1, y1, C3 and C2, instead of assuming that the same byte array works everywhere. State the exact standard/profile and encoding at each boundary.','部分旧描述及 API 输出 C1C2C3；现代配置和库可能选择 C1C3C2 或 ASN.1。本项目明确使用 04||x1||y1||C3||C2。OpenSSL 测试会转为含 x1、y1、C3、C2 的 DER 结构，不假设相同字节数组到处通用。每个边界都应列明标准 / 配置及编码。'),t('ECDSA is a signature scheme and provides no encryption equivalent. Compare SM2 encryption with a fully specified ECC encryption or encapsulation-plus-AEAD design, not with “NIST P-256” alone. Large-data protocols often use hybrid encryption, but their KDF, associated data and key separation require a defined construction.','ECDSA 是签名方案，没有对应加密功能。应将 SM2 加密与完整定义的 ECC 加密或封装 + AEAD 设计对比，而非只与“NIST P-256”对比。大数据协议常用混合加密，但 KDF、关联数据和密钥分离必须由明确构造定义。')),('gm-usage','sm2-draft','nist-kex','gb-sm2'))
    elif page=='sm2-exchange':
        add('keys','SM2 exchange mixes static and ephemeral keys','SM2 交换混合静态及临时密钥','A raw ECDH multiplication is not the complete SM2 exchange.','原始 ECDH 乘法不是完整 SM2 交换。',code('A: static dA, PA=[dA]G; ephemeral rA, RA=[rA]G\nB: static dB, PB=[dB]G; ephemeral rB, RB=[rB]G\nw=ceil(log2(n)/2)−1  (127 for curveSM2)\nx̄1=2ʷ+(xRA mod 2ʷ); x̄2=2ʷ+(xRB mod 2ʷ)\ntA=(dA+x̄1 rA) mod n; tB=(dB+x̄2 rB) mod n\nU=[h tA](PB+[x̄2]RB)\nV=[h tB](PA+[x̄1]RA)\nU=V for valid honest inputs')+p(t('Validate received points and reject infinity or invalid intermediate results. The shortened x-coordinate values are not hashes; their definition is part of the scheme. Both long-term and ephemeral secret scalars are used, so the protocol’s security claims must be read with the specified compromise model. “Uses ephemeral keys” by itself is not a blanket forward-secrecy proof.','应验证接收点，拒绝无穷远及无效中间结果。缩短的 x 坐标值不是哈希，其定义属于方案。协议使用长期及临时秘密标量，应按规定的泄漏模型理解安全主张。“使用临时密钥”本身不是前向保密的通用证明。')),('sm2-draft','gb-sm2'),'sm2-exchange')
        add('derive','Keep A/B ordering fixed in the KDF and confirmations','KDF 及确认中固定 A/B 顺序','The same shared point can produce different keys if identities are ordered differently.','身份顺序不同，相同共享点也会产生不同密钥。',code('K = KDF(xU || yU || ZA || ZB, klen)\ninner = SM3(xU || ZA || ZB || xRA || yRA || xRB || yRB)\nB confirmation = SM3(02 || yU || inner)\nA confirmation = SM3(03 || yU || inner)')+p(t('B sends the 02-prefixed tag and A checks it; when confirmation is used, A sends the 03-prefixed tag and B checks it. The outer role ordering is A then B even when B executes the calculation. Confirmation proves possession of the derived context under the protocol assumptions; it is not an authorization decision for every application action.','B 发送 02 前缀标签供 A 检查；启用确认时 A 发送 03 前缀标签供 B 检查。即使计算方是 B，外层角色顺序仍是 A 后 B。确认在协议假设下证明持有派生上下文，不是每项应用动作的授权决定。'),t('The download implements the algebraic core and both tags, with a test that changing an ID changes the key. It is not a network state machine: timeout, replay handling, role binding, certificate authentication, tag verification and key-release policy still belong to a real protocol implementation.','下载项目实现算术核心及两个标签，并测试 ID 改变导致密钥改变。它不是网络状态机；超时、重放处理、角色绑定、证书认证、标签验证及密钥释放策略仍属于真实协议实现。')),('sm2-draft','nist-kex'))
        add('tls','A protocol can use curveSM2 without using this exchange','协议可使用 curveSM2 而不使用这一交换','Identify the negotiated group and the actual key schedule.','识别协商组与实际密钥计划。',p(t('A TLS 1.3 key share on curveSM2 follows the TLS 1.3 handshake and key schedule selected by its profile. Do not label every multiplication on the SM2 curve as the GB/T 32918.3 static-plus-ephemeral exchange above. Likewise, SM2 signatures authenticate a transcript, while the TLS record cipher is an independent symmetric construction.','curveSM2 上的 TLS 1.3 KeyShare 遵循其配置选择的 TLS 1.3 握手及密钥计划。不能把 SM2 曲线上的所有乘法都称为上述 GB/T 32918.3 静态 + 临时交换。同样，SM2 签名认证 transcript，TLS 记录密码是独立对称构造。')),('tls-sm','tls13','gb-sm2'))
    elif page=='ecc-compare':
        from examples.reference import SM2,P256
        add('parameters','Same size, different groups','相同位数，不同群','All hexadecimal values below are exact domain parameters.','以下十六进制值均为精确域参数。',table([t('Parameter','参数'),'curveSM2','NIST P-256 / secp256r1'],[(label,'<code>'+f'{getattr(SM2,attr):064X}'+'</code>','<code>'+f'{getattr(P256,attr):064X}'+'</code>') for label,attr in [('p','p'),('a','a'),('b','b'),('n','n'),('Gx','gx'),('Gy','gy')]]+[('h','1','1')])+p(t('A P-256 field reduction routine cannot simply be renamed SM2: the moduli have different sparse forms. A generic big-integer ECC engine may support both after supplying the right complete domain and validation rules. Identical 32-byte coordinate widths do not make public points, private keys or certificates interchangeable.','P-256 域约减例程不能直接改名 SM2，二者模数稀疏形式不同。通用大整数 ECC 引擎可在提供完整正确域及验证规则后支持两者。相同 32 字节坐标宽度不意味着公钥点、私钥或证书可互换。')),('nist-curves','tls-sm'),'ecc-compare')
        add('schemes','Compare the equations, not just the curve names','比较等式，而不只比较曲线名','NIST curves specify domains; ECDSA and ECDH specify operations.','NIST 曲线定义域，ECDSA 与 ECDH 定义操作。',table([t('Aspect','维度'),'SM2 signature','ECDSA'],[(t('Message representative','消息代表'), 'e=SM3(ZA||M)',t('Hash of M, converted/truncated under the scheme rules','M 的哈希，按方案规则转换 / 截断')),(t('First component','第一分量'),'r=(e+x([k]G)) mod n','r=x([k]G) mod n'),(t('Second component','第二分量'),'s=(1+d)⁻¹(k−rd) mod n','s=k⁻¹(e+rd) mod n'),(t('Verification point','验签点'),'[s]G+[(r+s) mod n]P','[e s⁻¹]G+[r s⁻¹]P'),(t('Identity binding','身份绑定'),t('Explicit ZA input','明确 ZA 输入'),t('Not an intrinsic ECDSA input; protocol may bind identity separately','不是 ECDSA 固有输入，协议可另行绑定身份'))])+p(t('A raw ECDH core computes a shared point from one private scalar and a peer public point, followed by protocol-defined validation and derivation. SM2’s named exchange combines static and ephemeral keys plus ZA/ZB and confirmation. No mathematical curve substitution converts one complete scheme into the other.','原始 ECDH 核心以私钥标量和对端公钥计算共享点，再按协议验证及派生。SM2 命名交换组合静态 / 临时密钥、ZA/ZB 与确认。数学曲线替换不能把一种完整方案变成另一种。')),('nist-dss','nist-kex','sm2-draft'))
        add('families','Compare security level and representation separately','分别比较安全级别与表示','P-384 and P-521 are not 256-bit alternatives.','P-384 与 P-521 不是 256 位替代。',table([t('Domain','域'),t('Field bits / coordinate bytes','域位数 / 坐标字节'),t('Approximate classical level','约经典级别')],[('curveSM2','256 / 32',t('About 128 bits under generic ECC assumptions','通用 ECC 假设下约 128 位')),('NIST P-256','256 / 32','128'),('NIST P-384','384 / 48','192'),('NIST P-521','521 / 66','256')])+p(t('P-521 uses 66 bytes per coordinate and is not a “512-bit curve.” NIST SP 800-186 also covers other curve forms, including Edwards curves used by EdDSA. Edwards/Montgomery encodings and EdDSA operations are not drop-in SM2 or ECDSA replacements. secp256k1 is another 256-bit curve, but it is not NIST P-256.','P-521 每坐标使用 66 字节，不是“512 位曲线”。NIST SP 800-186 还包含其他曲线形式，包括 EdDSA 使用的 Edwards 曲线。Edwards / Montgomery 编码及 EdDSA 操作不能直接替代 SM2 或 ECDSA。secp256k1 是另一条 256 位曲线，但不是 NIST P-256。'),t('These comparisons are classical and do not confer standard approval. Large fault-tolerant quantum computation would threaten the discrete-log assumptions behind both SM2 and NIST ECC; migration is a protocol and key-lifecycle problem, not a change of curve branding.','这些比较属于经典模型，不表示标准批准。大规模容错量子计算会威胁 SM2 与 NIST ECC 的离散对数假设；迁移是协议及密钥生命周期问题，不是更换曲线品牌。')),('nist-curves','strength','pqc'))
    elif page=='sm3':
        add('padding','Parse bytes into 512-bit blocks and 32-bit words','将字节解析为 512 位分组和 32 位字','SM3 returns 256 bits, but its input block is 512 bits.','SM3 输出 256 位，但输入分组为 512 位。',code('Append 1 bit; append zeros until length ≡ 448 mod 512\nAppend original message length as a 64-bit big-endian integer\nIV = 7380166f 4914b2b9 172442d7 da8a0600\n     a96f30bc 163138aa e38dee4d b0fb0e4e\nEach block: 16 initial 32-bit big-endian words')+p(t('The length suffix is a bit count before padding. For byte input, the first added byte is 80. A 55-byte message fits into one block; a 56-byte message needs a second block for the length. All arithmetic additions below wrap modulo 2³²; rotation counts are reduced modulo 32. Implementations must not rely on unlimited Python integers or signed JavaScript shifts without explicit word handling.','长度后缀是填充前位数。字节输入的第一个附加字节为 80。55 字节消息可放在一个分组，56 字节消息需要第二分组容纳长度。以下加法均按 2³² 回绕，循环移位量按 32 约减。实现不能忽略 Python 无限整数或 JavaScript 有符号移位的字处理。')),('gb-sm3','sm3-draft'),'sm3')
        add('schedule','Expansion uses P1 and two related word streams','扩展使用 P1 与两组相关字序列','Do not substitute SHA-256’s sigma functions.','不能替换成 SHA-256 的 sigma 函数。',code('ROTL = 32-bit rotate left\nP0(X)=X XOR ROTL(X,9) XOR ROTL(X,17)\nP1(X)=X XOR ROTL(X,15) XOR ROTL(X,23)\nFor j=16..67:\n Wj=P1(Wj−16 XOR Wj−9 XOR ROTL(Wj−3,15))\n    XOR ROTL(Wj−13,7) XOR Wj−6\nFor j=0..63: W′j=Wj XOR Wj+4\nTj=79cc4519 (j<16); 7a879d8a (j≥16)')+p(t('The first stream has 68 words and the derived stream has 64; confusing these counts or the j+4 reference is a common indexing bug. P0 transforms a compression result; P1 transforms schedule inputs. They serve different positions and use different rotation constants.','第一序列有 68 个字，派生序列有 64 个；混淆数量或 j+4 引用是常见索引错误。P0 变换压缩结果，P1 变换扩展输入；二者位置及旋转常数不同。')),('sm3-draft'))
        add('compression','Inspect the full 64-round compression update','检查完整 64 轮压缩更新','The output feed-forward is XOR, not addition.','输出前馈是异或，不是加法。',code('For j<16: FF=A XOR B XOR C; GG=E XOR F XOR G\nFor j≥16: FF=(A&B)|(A&C)|(B&C); GG=(E&F)|(~E&G)\nSS1=ROTL((ROTL(A,12)+E+ROTL(Tj,j)) mod 2³²,7)\nSS2=SS1 XOR ROTL(A,12)\nTT1=(FF+D+SS2+W′j) mod 2³²\nTT2=(GG+H+SS1+Wj) mod 2³²\n(A,B,C,D) ← (TT1,A,ROTL(B,9),C)\n(E,F,G,H) ← (P0(TT2),E,ROTL(F,19),G)\nVnext=Vprevious XOR (A||B||C||D||E||F||G||H)')+p(t('After all padded blocks, serialize the eight final words big-endian. For ASCII abc, the result is 66c7f0f4…8f4ba8e0. The browser lab shows all compression rounds and padding length; the Python tests include 55/56/63/64/65-byte boundaries plus independent OpenSSL results. Matching abc alone would not detect every padding or multi-block bug.','处理全部填充分组后，将八个最终字大端序列化。ASCII abc 结果为 66c7f0f4…8f4ba8e0。浏览器实验显示全部压缩轮及填充长度；Python 测试包含 55/56/63/64/65 字节边界与 OpenSSL 独立结果。只匹配 abc 无法发现所有填充或多分组错误。')),('sm3-draft','openssl-sm3'))
    elif page=='hash-compare':
        add('architecture','Compare SM3, SHA-256, SHA-512 and SHA3-256','比较 SM3、SHA-256、SHA-512 与 SHA3-256','Same output length does not mean the same construction.','相同输出长度不意味着相同构造。',table([t('Property','属性'),'SM3','SHA-256','SHA-512','SHA3-256'],[(t('Structure','结构'),t('Iterated compression','迭代压缩'),t('Iterated compression','迭代压缩'),t('Iterated compression','迭代压缩'),t('Sponge / Keccak-f','海绵 / Keccak-f')),(t('Input block / rate','输入分组 / rate'),'512 bits','512 bits','1024 bits','1088-bit rate'),(t('Internal width','内部宽度'),'8 × 32-bit','8 × 32-bit','8 × 64-bit','25 × 64-bit = 1600'),(t('Output','输出'),'256 bits','256 bits','512 bits','256 bits'),(t('Rounds','轮数'),'64','64','80','24 / permutation'),(t('Schedule','扩展'),'68 W + 64 W′','64 W','80 W',t('Absorb bytes into rate; no analogous W schedule','字节吸收到 rate，无对应 W 扩展')),(t('Feed-forward','前馈'),'XOR',t('Word addition','按字加法'),t('Word addition','按字加法'),t('No compression feed-forward of that form','没有这种压缩前馈形式')),(t('Length suffix','长度后缀'),'64-bit','64-bit','128-bit',t('Domain suffix plus sponge padding','域后缀及海绵填充'))])+p(t('SM3 and SHA-256 share word width, block size and round count, yet differ in IV, constants, schedule, Boolean-function schedule, state updates and final feed-forward. SHA-512 is not SHA-256 with twice the output buffer: it uses 64-bit words, different rotations, larger blocks and 80 rounds. SHA-512/256 is a separate IV-defined variant, not naive truncation of ordinary SHA-512.','SM3 与 SHA-256 的字宽、分组和轮数相同，但 IV、常数、扩展、布尔函数阶段、状态更新及最终前馈不同。SHA-512 不是把 SHA-256 输出缓冲加倍，它使用 64 位字、不同旋转、更大分组及 80 轮。SHA-512/256 有独立 IV，不是简单截断普通 SHA-512。')),('sm3-draft','sha2','sha3'),'hash-compare')
        add('rounds','SHA-256 compression uses different functions and constants','SHA-256 压缩使用不同函数及常数','It has eight working words but no SM3 P0/P1 functions.','它有八个工作字，但没有 SM3 的 P0 / P1。',code('SHA-256 (32-bit ROTR):\nCh(x,y,z)=(x & y) XOR (~x & z)\nMaj(x,y,z)=(x & y) XOR (x & z) XOR (y & z)\nσ0(x)=ROTR(x,7) XOR ROTR(x,18) XOR (x >> 3)\nσ1(x)=ROTR(x,17) XOR ROTR(x,19) XOR (x >> 10)\nWj=σ1(Wj−2)+Wj−7+σ0(Wj−15)+Wj−16 mod 2³²\nΣ0(a)=ROTR(a,2) XOR ROTR(a,13) XOR ROTR(a,22)\nΣ1(e)=ROTR(e,6) XOR ROTR(e,11) XOR ROTR(e,25)\nT1=h+Σ1(e)+Ch(e,f,g)+Kj+Wj mod 2³²\nT2=Σ0(a)+Maj(a,b,c) mod 2³²\nnew a=T1+T2; new e=d+T1 (mod 2³²)\nOther registers shift; final chaining words ADD old words')+p(t('SHA-256 uses 64 different round constants rather than SM3’s two base constants rotated by round number. Endianness happens to agree for their parsed 32-bit words, which can hide a wrong-core implementation behind correct byte handling. Use known answers from each algorithm instead of just checking the digest length.','SHA-256 使用 64 个不同轮常数，而不是 SM3 按轮号旋转的两个基础常数。二者解析 32 位字时恰巧都是大端，这可能让正确字节处理掩盖错误核心。应分别使用各算法已知答案，而不是只检查摘要长度。')),('sha2','sm3-draft'))
        add('sponge','SHA-3 absorbs, permutes and squeezes','SHA-3 吸收、置换并挤出','For SHA3-256, rate=1088 and capacity=512 bits.','SHA3-256 的 rate=1088、capacity=512 位。',code('Keccak-f[1600]: 5×5 lanes, each 64 bits\nEach of 24 rounds: θ → ρ → π → χ → ι\nAbsorb: XOR each padded 136-byte block into the rate lanes\nPermute the whole 1600-bit state\nSqueeze: read 32 digest bytes from rate\nSHA3 byte-aligned suffix: 06; final padding bit: 80\nLane byte order: little-endian')+p(t('θ mixes column parity; ρ rotates lanes; π relocates lanes; χ is a nonlinear row step; ι XORs the round constant into one lane. Capacity is not directly filled by the message. The SHA3 domain suffix distinguishes it from original Keccak-256, which produces different digests despite the same permutation, rate and output size.','θ 混合列奇偶，ρ 旋转 lane，π 重新排列 lane，χ 是非线性行变换，ι 将轮常数异或到一个 lane。消息不直接填充 capacity。SHA3 域后缀使它不同于原始 Keccak-256；即使置换、rate、输出长度相同，摘要也不同。'),t('SHAKE128 and SHAKE256 are XOFs with variable output lengths and different domain separation. Naming SHAKE256 does not specify a 256-bit digest; applications must request sufficient output and follow the construction’s rules. KMAC uses a defined keyed SHA-3 construction, not an arbitrary secret prefix.','SHAKE128 / SHAKE256 是输出长度可变、域分离不同的 XOF。SHAKE256 名称不指定 256 位摘要；应用须请求足够输出并遵循构造规则。KMAC 是明确定义的带密钥 SHA-3 构造，不是任意秘密前缀。')),('sha3','sp185'))
        add('security','A plain hash is neither encryption nor a MAC','普通杂凑不是加密，也不是 MAC','Security goals and output sizes must be stated explicitly.','应明确安全目标与输出长度。',p(t('For an ideal 256-bit digest, generic classical collision search is about 2¹²⁸ work and generic preimage search about 2²⁵⁶. These are generic ceilings/models, not proofs that every algorithm or implementation achieves them. SHA-512 offers a 512-bit digest with different generic bounds; SHA3-256’s capacity also matters to its sponge analysis. Do not rank algorithms from an avalanche screenshot or a toy timing measurement.','理想 256 位摘要的通用经典碰撞搜索约需 2¹²⁸ 工作量、原像搜索约 2²⁵⁶。这些是通用界限 / 模型，不是每个算法或实现均达到它们的证明。SHA-512 输出 512 位，通用界限不同；SHA3-256 的海绵分析还依赖 capacity。不能凭雪崩截图或玩具计时给算法安全性排名。'),t('SM3 and SHA-256 expose a Merkle–Damgård-style chaining state and permit classical length extension when a digest is misused as authentication of secret||message. Use HMAC or a specified MAC instead. Standard SHA-3 does not expose the full sponge state and does not have the same ordinary length-extension behavior; that still does not turn an unkeyed hash into authentication.','SM3 与 SHA-256 暴露类似 Merkle–Damgård 的链接状态，当 secret||message 摘要被误作认证时可出现经典长度扩展。应使用 HMAC 或规定 MAC。标准 SHA-3 不暴露完整海绵状态，没有同样普通长度扩展行为，但无密钥哈希仍不因此成为认证。')),('hmac','sha2','sha3','sp185'))
    elif page=='sm4':
        add('core','Four 32-bit words rotate through a 32-round core','四个 32 位字经过 32 轮核心','SM4 has one standardized key length: 128 bits.','SM4 标准密钥长度为 128 位。',code('Input block: X0,X1,X2,X3 (big-endian 32-bit words)\nFor i=0..31:\n Xi+4 = Xi XOR T(Xi+1 XOR Xi+2 XOR Xi+3 XOR rki)\n T = L ∘ τ\n τ: apply the fixed 8-bit SM4 S-box to each byte\n L(B)=B XOR ROTL(B,2) XOR ROTL(B,10)\n      XOR ROTL(B,18) XOR ROTL(B,24)\nOutput: X35 || X34 || X33 || X32')+p(t('SM4 is commonly described as a generalized Feistel-type word structure. The final reversal is part of encryption, not an optional byte-order choice. The S-box is not the AES S-box. A 128-bit plaintext plus a 128-bit key always produces a 128-bit block; there is no padding inside the primitive.','SM4 常被描述为广义 Feistel 类字结构。最终反序是加密的一部分，不是可选字节序。S 盒不是 AES S 盒。128 位明文与 128 位密钥产生 128 位分组；原语内部没有填充。')),('gb-sm4','sm4-draft'),'sm4')
        add('keys','The key schedule uses a different linear transform','密钥计划使用不同线性变换','L and L′ must not be mixed.','不能混用 L 与 L′。',code('K0..K3 = MK0..MK3 XOR FK0..FK3\nFK = a3b1bac6 56aa3350 677d9197 b27022dc\nCKi,j = ((4i+j)×7) mod 256, j=0..3\nCKi = four CK bytes in big-endian order\nKi+4 = Ki XOR T′(Ki+1 XOR Ki+2 XOR Ki+3 XOR CKi)\nT′ = L′ ∘ τ\nL′(B)=B XOR ROTL(B,13) XOR ROTL(B,23)\nrki = Ki+4')+p(t('Data rounds and key expansion share the byte S-box but use different rotations. Encryption applies rk0 through rk31; decryption uses the same round transform with rk31 through rk0, followed by the same output reversal. An inverse S-box is not required for SM4 decryption.','数据轮与密钥扩展共享字节 S 盒，但旋转不同。加密使用 rk0 至 rk31，解密以相同轮变换使用 rk31 至 rk0，再做相同输出反序。SM4 解密不需要逆 S 盒。')),('sm4-draft'))
        add('vectors','Trace a standard single-block known answer','跟踪标准单分组已知答案','This is a primitive test, not an ECB data-encryption recommendation.','这是原语测试，不是 ECB 数据加密建议。',code('Key   = 0123456789abcdeffedcba9876543210\nInput = 0123456789abcdeffedcba9876543210\nrk0   = f12186f9\nX4    = 27fad345\nOutput= 681edf34d206965e86b3e94f536e4246')+p(t('The lab shows all 32 round keys and generated words, then checks decryption with reversed keys. Independent OpenSSL tests use several different keys and blocks as well as the published example. Table-based S-box lookups are easy to read but can leak through caches; mathematical correctness does not establish constant-time behavior.','实验显示全部 32 轮密钥和生成字，再以逆序密钥检查解密。OpenSSL 独立测试除公开例子外，还使用多组不同密钥及分组。查表 S 盒易读，但可能经缓存泄漏；数学正确不证明恒定时间。')),('sm4-draft','openssl-sm4'))
    elif page=='aes-compare':
        add('dimensions','Match SM4 with AES-128 before widening the comparison','先将 SM4 与 AES-128 对齐，再扩大比较','AES-256’s key is longer; its block is still 128 bits.','AES-256 的密钥更长，分组仍为 128 位。',table([t('Property','属性'),'SM4','AES-128','AES-192','AES-256'],[(t('Key / block bits','密钥 / 分组位数'),'128 / 128','128 / 128','192 / 128','256 / 128'),(t('Rounds','轮数'),'32','10','12','14'),(t('Internal view','内部视图'),'4 × 32-bit words','4 × 4 bytes','4 × 4 bytes','4 × 4 bytes'),(t('Structure','结构'),t('Generalized Feistel-type','广义 Feistel 类'),'SPN','SPN','SPN'),(t('Round key width','轮密钥宽度'),'32 bits','128 bits','128 bits','128 bits'),(t('Key schedule output','密钥计划输出'),'32 × 32 bits','11 × 128 bits','13 × 128 bits','15 × 128 bits'),(t('Decryption','解密'),t('Same F; reversed round keys','相同 F，逆序轮密钥'),t('Inverse operations / equivalent inverse cipher','逆操作 / 等价逆密码'),t('Inverse operations','逆操作'),t('Inverse operations','逆操作'))])+p(t('Counting rounds is not a security ranking: an SM4 round transforms one new word, while an AES round transforms the full byte state. They have different nonlinear layers, diffusion and key schedules. Security assessment requires attacks against the exact full algorithm and assumptions, not “32 is greater than 10.”','轮数不能直接排名安全性：SM4 一轮变换一个新字，AES 一轮变换整个字节状态。非线性层、扩散和密钥计划不同。安全评估需要针对精确完整算法及假设的攻击分析，而不是“32 大于 10”。')),('aes','sm4-draft'),'aes-compare')
        add('aes-round','AES works on a column-major 4×4 byte state','AES 使用按列映射的 4×4 字节状态','ShiftRows and MixColumns operate on different dimensions.','ShiftRows 与 MixColumns 作用于不同维度。',code('state[row,col] = input[4×col+row]\nInitial: AddRoundKey\nOrdinary round: SubBytes → ShiftRows → MixColumns → AddRoundKey\nFinal round: SubBytes → ShiftRows → AddRoundKey (no MixColumns)\nAES S-box: inverse in GF(2⁸), then affine transform\nGF polynomial: x⁸+x⁴+x³+x+1 (0x11b)\nMixColumns matrix:\n 02 03 01 01\n 01 02 03 01\n 01 01 02 03\n 03 01 01 02')+p(t('SubBytes substitutes every byte. ShiftRows cyclically rotates rows; MixColumns multiplies each column by a fixed GF(2⁸) matrix. AddRoundKey XORs a full 16-byte round key. SM4 instead applies its S-box to a four-byte word and diffuses through 32-bit rotations; copying AES’s state layout into an SM4 port changes the algorithm.','SubBytes 替换每个字节，ShiftRows 循环移位各行，MixColumns 以固定 GF(2⁸) 矩阵乘每列，AddRoundKey 异或完整 16 字节轮密钥。SM4 则对四字节字做 S 盒并经 32 位旋转扩散；把 AES 状态布局搬入 SM4 移植会改变算法。')),('aes','sm4-draft'))
        add('expansion','AES key expansion also differs across key sizes','AES 密钥扩展也随密钥大小变化','AES-256 has an extra SubWord branch.','AES-256 有额外 SubWord 分支。',code('Nk = 4 / 6 / 8 words; Nr = 10 / 12 / 14\ntemp = w[i−1]\nif i mod Nk = 0:\n temp = SubWord(RotWord(temp)) XOR Rcon[i/Nk]\nelse if Nk > 6 and i mod Nk = 4:\n temp = SubWord(temp)\nw[i] = w[i−Nk] XOR temp\nGenerate 4×(Nr+1) words')+p(t('AES-128’s initial key is the round-zero key; SM4’s FK XOR and T′ expansion are a different procedure. The download includes readable AES-128 encryption so that its ten states can be compared with SM4’s generated words, and validates it with the FIPS known answer 69c4e0d8…70b4c55a plus independent OpenSSL checks. It does not implement AES-192/256 or a production mode API.','AES-128 初始密钥是第零轮密钥；SM4 的 FK 异或和 T′ 扩展是不同过程。下载项目包含可读 AES-128 加密，便于将十个状态与 SM4 生成字对照，并以 FIPS 已知答案 69c4e0d8…70b4c55a 及 OpenSSL 独立结果验证。它不实现 AES-192/256 或生产模式 API。'),t('Performance depends on implementation, CPU instructions, mode parallelism, message length and setup cost. A vendor’s accelerated result is not a universal SM4/AES speed ratio. Benchmark the same mode, hardware, library build and workload before choosing an engineering path.','性能取决于实现、CPU 指令、模式并行性、消息长度及设置成本。厂商加速结果不是通用 SM4 / AES 速度比；选择工程路径前，应对相同模式、硬件、库构建和工作负载测试。')),('aes','openssl-sm4','family'))
    elif page=='modes':
        add('confidentiality','A correct block core still needs a correct mode','正确分组核心仍需正确模式','Changing AES to SM4 does not repair a broken nonce policy.','把 AES 换成 SM4 不会修复错误 Nonce 策略。',table([t('Construction','构造'),t('Main requirement','主要要求'),t('Authentication?','提供认证？')],[('ECB',t('Repeated equal blocks expose patterns; only used here for primitive tests','重复相同分组暴露模式，本站仅用于原语测试'),t('No','否')),('CBC',t('Unpredictable IV, defined padding, separate integrity; avoid padding oracles','不可预测 IV、明确填充及独立完整性，避免填充预言机'),t('No','否')),('CTR',t('Never repeat counter/nonce blocks with the same key','同密钥下不能重复计数器 / Nonce 分组'),t('No','否')),('GCM',t('Nonce uniqueness, tag verification, bounds and associated data','Nonce 唯一、标签验证、边界及关联数据'),t('AEAD','AEAD')),('CCM',t('CTR plus CBC-MAC with its specified lengths/nonce format','按规定长度 / Nonce 格式组合 CTR 与 CBC-MAC'),t('AEAD','AEAD'))])+p(t('ECB, CBC and CTR provide confidentiality functions, not an authenticated application format. CTR nonce reuse repeats a keystream, exposing XOR relationships between plaintexts. GCM nonce reuse can also compromise authentication. AES-GCM and SM4-GCM use a 128-bit block cipher underneath the mode, but produce different outputs and remain different negotiated algorithms.','ECB、CBC、CTR 提供机密性功能，不是已认证应用格式。CTR 重用 Nonce 会重复密钥流、暴露明文间异或关系；GCM 重用还可能破坏认证。AES-GCM 与 SM4-GCM 底层都是 128 位分组密码，但结果不同，仍是不同协商算法。')),('modes','gcm','ccm','tls-sm'),'modes')
        add('authentication','Use a MAC or AEAD for authenticity','使用 MAC 或 AEAD 提供真实性','SM3 alone cannot tell whether a sender knew a secret.','单独 SM3 无法判断发送者是否掌握秘密。',code('HMAC-SM3 uses a 64-byte hash block:\nHMAC(K,M)=SM3((K′ XOR opad) || SM3((K′ XOR ipad) || M))\nipad=36 repeated; opad=5c repeated\nNormalize K to the hash block width under HMAC rules')+p(t('Do not create a homemade “SM3 MAC” by prepending or appending a secret. Use the construction selected by the protocol, with separate keys for distinct purposes. An AEAD tag authenticates associated data without encrypting it; that is useful for binding algorithm/version identifiers and message context. Verify the tag before delivering plaintext to an application.','不能靠秘密前缀或后缀自造“SM3 MAC”。应使用协议选择的构造，并为不同用途分离密钥。AEAD 标签认证但不加密关联数据，可绑定算法 / 版本标识和消息上下文。应用接收明文前应先验证标签。')),('hmac','gcm','sp185'))
        add('lifecycle','Key length is only one lifecycle property','密钥长度只是生命周期中的一项属性','State, rotation, uniqueness and recovery matter.','状态、轮换、唯一性及恢复同样重要。',p(t('Specify key generation, storage, purpose, algorithm identifier, nonce allocation, use limits, rotation and deletion. Coordinate nonce allocation across processes and restarts rather than assuming one counter never resets. Authentication failures should not expose sensitive intermediate plaintext or create distinguishable decryption behavior.','应规定密钥生成、存储、用途、算法标识、Nonce 分配、使用上限、轮换及删除。Nonce 分配需跨进程及重启协调，不能假定某个计数器永不重置。认证失败不应暴露敏感中间明文或形成可区分解密行为。')),('strength','gcm','ccm'))
    elif page=='sm9':
        add('model','SM9 changes how users obtain private keys','SM9 改变用户取得私钥的方式','A public identity is combined with system parameters and a key-generation authority.','公开身份与系统参数、密钥生成机构组合。',p(t('SM9 is identity-based public-key cryptography. A key generation centre (KGC) holds a master secret and derives a user’s private key from an identity and the relevant algorithm domain. A verifier or encryptor uses the identity together with master public parameters; the identity is not secretly converted into an ordinary SM2 key pair by the user.','SM9 属于基于标识的公钥密码。密钥生成中心 KGC 持有主秘密，按身份和相应算法域派生用户私钥。验证者或加密者使用身份和主公有参数；并非用户偷偷把身份转换为普通 SM2 密钥对。'),t('The family includes signatures, exchange, key encapsulation and encryption. Identities need a defined byte representation, domain, lifecycle and renewal/revocation policy. Embedding a validity period in an identifier changes the key namespace; it does not automatically implement a complete revocation system.','算法族包含签名、交换、密钥封装及加密。身份需要明确字节表示、域、生命周期及更新 / 撤销策略。把有效期写进标识会改变密钥命名空间，但不自动实现完整撤销系统。')),('gb-sm9','gmssl'),'sm9')
        add('pairing','Pairings are more than ordinary ECC scalar multiplication','双线性对不只是普通 ECC 标量乘','SM9 uses different groups and extension-field arithmetic.','SM9 使用不同群及扩域算术。',code('Pairing: e : G1 × G2 → GT\nBilinearity: e([a]P,[b]Q)=e(P,Q)^(ab)\nImplementation layers: base field → extension fields → curve groups\n                      → pairing / final exponentiation → scheme')+p(t('The standardized SM9 parameters use a pairing-friendly BN curve with embedding degree 12. G1, G2 and GT have different representations and operations. A point in G2 is not simply another curveSM2 public key, and a target-group value is not a point with two 32-byte coordinates. Production validation must follow the exact group, subgroup and encoding rules.','标准 SM9 参数采用嵌入次数 12 的配对友好 BN 曲线。G1、G2、GT 的表示和操作不同；G2 点不是另一种 curveSM2 公钥，目标群值也不是两个 32 字节坐标的点。生产验证应遵守具体群、子群及编码规则。'),t('A 256-bit pairing-friendly base field cannot be assigned the same strength as P-256 merely by counting bits: attacks also involve the target extension field. Read current pairing cryptanalysis and the chosen parameter set. This atlas does not claim a universal numerical security level for SM9 from its field size.','不能只数位数便给 256 位配对友好基域赋予 P-256 相同强度；攻击还涉及目标扩域。应阅读当前配对密码分析及所选参数。本网站不从域大小推导 SM9 通用数字安全强度。')),('gb-sm9','gmssl'))
        add('trust','KGC simplifies one trust problem and adds another','KGC 简化一种信任问题，同时引入另一种','Master-key compromise has a wide blast radius.','主密钥失陷影响范围很广。',p(t('A KGC can derive user private keys in its domain; the trust model therefore includes key escrow or an equivalent authority assumption. Protect the master secret, enrollment, distribution and renewal channels. Knowing that a message matches an identity does not prove that its private key was exclusively controlled by the named person.','KGC 能派生其域中用户私钥，信任模型因此包含密钥托管或等价机构假设。应保护主秘密、注册、分发及更新通道。消息匹配某身份，不证明其私钥仅由该身份本人控制。'),t('SM2 users usually generate their own key pairs and use external certificates or directories for identity binding. SM9 moves that binding into an identity-based system, with different authority and revocation consequences. Neither approach is inherently post-quantum: their algebraic assumptions remain exposed to sufficiently capable quantum algorithms.','SM2 用户通常生成自身密钥对，再以证书或目录绑定身份。SM9 将绑定移到标识密码系统，产生不同机构权限和撤销后果。二者都不是天然抗量子，代数假设仍暴露于足够强的量子算法。')),('gb-sm9','x509','pqc'))
    elif page=='zuc':
        add('state','ZUC generates a stateful keystream','ZUC 生成有状态密钥流','A stream cipher is not a 128-bit block cipher.','流密码不是 128 位分组密码。',p(t('The original ZUC-128 core takes a 128-bit key and 128-bit IV. It combines a 16-stage 31-bit LFSR, bit reorganization and a nonlinear function with two 32-bit registers and S-box processing. The LFSR operates with arithmetic tied to 2³¹−1, not SM3/SM4’s modulo-2³² word additions. Initialization and working phases are different.','原始 ZUC-128 核心输入 128 位密钥及 128 位 IV，组合 16 级 31 位 LFSR、比特重组，以及含两个 32 位寄存器和 S 盒处理的非线性函数。LFSR 运算与 2³¹−1 相关，不是 SM3 / SM4 的模 2³² 字加法。初始化与工作阶段不同。'),t('Working output is a sequence of 32-bit keystream words. For encryption, XOR the appropriate bits with the message according to the selected profile. Repeating a key/IV repeats a keystream and exposes relations between plaintexts. Confidentiality alone does not provide integrity.','工作输出是 32 位密钥流字序列。加密时按所选配置将相应位与消息异或。重复密钥 / IV 会重复密钥流、暴露明文间关系。机密性本身不提供完整性。')),('zuc','gm-index'),'zuc')
        add('profiles','EEA3 and EIA3 are different uses of the core','EEA3 与 EIA3 是核心的不同使用','Message counters and radio context are part of the input profile.','消息计数器及无线上下文属于输入配置。',p(t('128-EEA3 provides a confidentiality profile and 128-EIA3 an integrity profile for mobile communications. They define how count, bearer, direction, length and other context are encoded; they are not interchangeable arbitrary calls to “ZUC encrypt.” Test data includes bit-level lengths, so a byte-only harness can miss errors.','128-EEA3 提供移动通信机密性配置，128-EIA3 提供完整性配置。它们定义计数、承载、方向、长度等上下文如何编码，并非可互换的任意“ZUC 加密”调用。测试数据包含按位长度，仅按字节的测试工具可能遗漏错误。'),t('Compare ZUC encryption with a complete stream or CTR confidentiality construction, and its integrity profile with the specified integrity algorithm. Comparing “ZUC versus AES” without naming a mode or traffic profile mixes different layers.','ZUC 加密应与完整流密码或 CTR 机密性构造对比，完整性配置应与规定完整性算法对比。不指定模式或流量配置便比较“ZUC 与 AES”，会混淆层次。')),('zuc','modes'))
        add('variants','A 256-bit ZUC profile has its own specification','256 位 ZUC 配置有独立规范','Do not extend ZUC-128 by appending key bytes.','不能给 ZUC-128 追加密钥字节来扩展。',p(t('3GPP’s newer 256-bit algorithm set includes ZUC-based 256-NEA6, 256-NIA6 and 256-NCA6 specifications in the TS 35.246–35.248 family. These are release-specific profiles with separate initialization, formats and test data. Check the actual release and document version instead of inferring compatibility from the ZUC name.','3GPP 较新的 256 位算法集包含基于 ZUC 的 256-NEA6、256-NIA6、256-NCA6，位于 TS 35.246–35.248 标准族。它们是具有独立初始化、格式及测试数据的 Release 配置。应检查实际 Release 与文档版本，不能从 ZUC 名称推断兼容。'),t('The atlas explains ZUC’s model and reading route; it does not supply a full radio-protocol implementation. The publisher’s implementation/use conditions should be read alongside a technical specification when integrating it into a product.','本网站解释 ZUC 模型及阅读路径，不提供完整无线协议实现。集成产品时，应同时阅读技术规范与发布者实施 / 使用条件。')),('zuc256','zuc'))
    elif page=='protocols':
        add('suite','Four algorithm decisions occur in a TLS handshake','TLS 握手包含四类算法决策','A TLS 1.3 cipher suite does not name the signature algorithm.','TLS 1.3 密码套件不命名签名算法。',table([t('Layer','层次'),t('RFC 8998 identifier / job','RFC 8998 标识 / 功能')],[(t('Record AEAD + handshake hash','记录 AEAD + 握手哈希'),'TLS_SM4_GCM_SM3 (0x00C6); TLS_SM4_CCM_SM3 (0x00C7)'),(t('SignatureScheme','签名方案'),'sm2sig_sm3 (0x0708)'),(t('Supported group / KeyShare','支持组 / KeyShare'),'curveSM2 (41 / 0x0029)'),(t('Certificate trust','证书信任'),t('Separate certificate, chain, identity, validity and policy checks','独立证书、证书链、身份、有效期及策略检查'))])+p(t('RFC 8998 specifies SM algorithms within TLS 1.3; it is not a generic “turn on GM” switch for every browser or TLS library. Certificate key type, transcript signature, negotiated group and record AEAD must all be compatible with the exact profile. A successful SM2 primitive test does not prove a complete TLS handshake will interoperate.','RFC 8998 将国密算法用于 TLS 1.3，不是所有浏览器或 TLS 库的通用“开启国密”开关。证书密钥类型、transcript 签名、协商组及记录 AEAD 都须匹配精确配置。SM2 原语测试成功，不证明完整 TLS 握手可互操作。')),('tls-sm','tls13'),'protocols')
        add('identity','The protocol determines SM2 identity context','协议决定 SM2 身份上下文','Handshake signatures and certificate verification can use different IDs.','握手签名与证书验证可能使用不同 ID。',p(t('RFC 8998 defines a TLS-profile ID TLSv1.3+GM+Cipher+Suite for its specified handshake uses and discusses the common 1234567812345678 value for peer-certificate verification, while noting CA-specific variation. Do not hard-code one ID into every signature operation. Match the certificate issuer’s profile and the handshake role.','RFC 8998 为其规定握手用途定义 TLSv1.3+GM+Cipher+Suite 这一 TLS 配置 ID，并讨论对端证书验证常见的 1234567812345678，同时指出 CA 可能不同。不能把单一 ID 硬编码进所有签名操作；应匹配证书签发者配置及握手角色。'),t('An SM2 public-key OID, an sm2-with-SM3 signature OID and the TLS SignatureScheme are separate identifiers. A raw 64-byte signature may need DER encoding at another interface. Correctly parsing a certificate does not establish trust in its issuer or confirm the peer’s hostname.','SM2 公钥 OID、sm2-with-SM3 签名 OID 与 TLS SignatureScheme 是不同标识。原始 64 字节签名在另一接口可能需要 DER。正确解析证书不证明信任其签发者，也不确认对端主机名。')),('tls-sm','x509','openssl-sm2'))
        add('tlcp','TLCP is an independent transport protocol direction','TLCP 是独立的传输协议方向','Sharing primitives does not imply sharing the handshake.','共用原语不意味着共用握手。',p(t('GB/T 38636-2020 defines TLCP. Its handshake and certificate/key roles must be read from that protocol and selected profile; deployments can use distinct signing and encryption certificate roles. Do not copy those assumptions into TLS 1.3, or describe TLCP merely as TLS 1.3 with SM4 substituted for AES.','GB/T 38636-2020 定义 TLCP。其握手及证书 / 密钥角色应按协议与所选配置阅读；部署可能区分签名与加密证书角色。不能将这些假设搬入 TLS 1.3，也不能把 TLCP 简化为 TLS 1.3 将 AES 换成 SM4。'),t('For interoperability, record the library/version, protocol version, cipher suite, group, identity bytes, certificate roles, trust anchor and encoding. Compare actual negotiated values and rejection logs, not a marketing label saying the endpoint supports SM2/3/4.','互操作记录应包括库 / 版本、协议版本、套件、组、身份字节、证书角色、信任锚及编码。应比较实际协商值及拒绝日志，而非“支持 SM2/3/4”的宣传标签。')),('tlcp','gmssl','tls-sm'))
    elif page=='engineering':
        add('layers','Readable reference code and production code serve different purposes','可读参考代码与生产代码用途不同','Functional correctness does not establish resistance to leakage.','功能正确不证明抗泄漏能力。',p(t('The downloaded affine ECC implementation branches on scalar bits, uses variable-time Python integers and performs modular inversions. The block-cipher examples use indexed S-boxes; browser runtimes add JIT and memory-management behavior. These properties are useful for inspection and unsafe for handling valuable secrets. Use a reviewed implementation with an appropriate constant-time and platform strategy in real systems.','下载的仿射 ECC 实现按标量位分支，使用变时 Python 整数并求模逆。分组示例使用索引 S 盒；浏览器运行时还加入 JIT 与内存管理行为。这些特征便于观察，不适合处理有价值秘密。真实系统应使用经审查、具有适当恒定时间及平台策略的实现。'),t('Consider timing, caches, branch predictors, speculative execution, power/EM leakage and fault injection according to the attacker’s access. Rejecting a bad point is not enough if key-dependent processing happened first. Authentication compares should avoid obvious early-exit behavior, but replacing one comparison does not make the whole program constant-time.','应按攻击者接触能力分析时间、缓存、分支预测、瞬态执行、功耗 / 电磁及故障注入。若先发生密钥相关处理，之后拒绝坏点仍不足够。认证比较应避免明显提前退出，但替换一项比较不能让整个程序恒定时间。')),('openssl-sm2','gmssl','nist-kex'),'engineering')
        add('randomness','Randomness and exact parsing are part of implementation','随机数与精确解析属于实现','Successful round trips can coexist with severe security bugs.','往返成功仍可能存在严重安全漏洞。',p(t('Generate keys/nonces with a CSPRNG and unbiased range sampling. Enforce scalar/point bounds, maximum message sizes, exact field widths, bit/byte units and strict DER structures. Track randomness failures and reinitialization. A statistical test suite can detect some defects, but passing randomness tests does not prove unpredictability of a generator or protection of its state.','应以 CSPRNG 及无偏区间采样生成密钥 / Nonce；强制标量 / 点范围、最大消息长度、精确域宽、位 / 字节单位及严格 DER 结构。应处理随机源失败与重新初始化。统计测试可发现部分缺陷，但通过测试不证明生成器不可预测或状态受保护。'),t('High-level SM2 APIs may internally compute ZA and hash the message; low-level APIs may accept a digest. Verify which bytes the API consumes before hashing yourself. For symmetric APIs, explicitly select mode, IV/nonce, padding, tag length and associated data. API defaults can change across versions.','高层 SM2 API 可能内部计算 ZA 并哈希消息，低层 API 可能接收摘要。自行哈希前须确认 API 接收哪些字节。对称 API 应明确模式、IV / Nonce、填充、标签长度及关联数据；默认值可能随版本变化。')),('openssl-sm2','openssl-sm3','openssl-sm4','strength'))
        add('acceleration','Acceleration support must be measured on the installed platform','加速支持应按实际安装平台测量','An instruction name is not a guarantee for every build.','指令名称不是每种构建的保证。',p(t('Optimized implementations may use dedicated instructions, SIMD, bitslicing/fixslicing or vectorized multi-buffer processing. AES and SM4 instruction support differs by architecture and CPU feature set; GCM adds another authentication workload. Check runtime feature detection and provider dispatch instead of assuming a platform can accelerate every GM primitive.','优化实现可使用专用指令、SIMD、bitslicing / fixslicing 或向量化多缓冲处理。AES 与 SM4 指令支持随架构和 CPU 特征不同；GCM 还增加认证负载。应检查运行时特征检测及 Provider 分派，不假定平台能加速所有国密原语。'),t('A meaningful performance comparison fixes cipher/mode, key size, payload sizes, message counts, setup reuse, CPU, compiler flags and library version. Keep test vectors, independent-library checks, protocol interoperability and product assurance as separate validation records.','有意义的性能比较应固定密码 / 模式、密钥大小、负载长度、消息数、设置复用、CPU、编译参数及库版本。标准向量、独立库检查、协议互操作和产品保障应分别保留验证记录。')),('family','gmssl','openssl-sm4'))
    elif page=='practice':
        add('download','Run a complete local reference project','运行完整本地参考项目','No package installation is required for the Python core.','Python 核心无需安装额外包。','<p><a class="button" href="examples.zip">'+t('Download reference project ZIP ↓','下载参考项目 ZIP ↓')+'</a></p>'+code('cd gm-sm-atlas-examples\npython3 -B test_reference.py\npython3 -B demo.py')+p(t('Requires Python 3.9 or newer. The code includes SM3 compression, SM4 expansion/encryption/decryption, AES-128 encryption, curveSM2/P-256 point arithmetic, SM2 signature/verification, C1C3C2 encryption/decryption and the SM2 exchange algebra with confirmation tags. SHA-256/SHA3-256 comparisons in the CLI use Python hashlib.','需要 Python 3.9 或更新。代码包含 SM3 压缩、SM4 扩展 / 加解密、AES-128 加密、curveSM2 / P-256 点运算、SM2 签名验签、C1C3C2 加解密及含确认标签的 SM2 交换算术。命令行 SHA-256 / SHA3-256 对比使用 Python hashlib。'),t('All fixed private scalars and nonces in examples are deliberately public synthetic test values. Do not use them as real keys and do not enter private keys into the browser labs. The reference is readable, bounded teaching code with no constant-time guarantee, not a certified cryptographic module.','例子中的固定私钥标量与 Nonce 都是刻意公开的合成测试值，不能作为真实密钥，也不要向浏览器实验输入私钥。参考实现是便于阅读、有教学边界但无恒定时间保证的代码，不是认证密码模块。')),('gmssl','openssl-sm2'),'practice')
        add('evidence','Known answers plus an independent implementation','已知答案加独立实现','Ten test methods cover many values and rejection paths.','十个测试方法覆盖多组数值及拒绝路径。',table([t('Check','检查'),t('Evidence','证据')],[(t('SM3','SM3'),t('abc and 64-byte published vectors; 10 OpenSSL-checked lengths around padding boundaries','abc 与 64 字节公开向量；10 组含填充边界长度经 OpenSSL 检查')),(t('SM4 / AES-128','SM4 / AES-128'),t('Published single-block answers and 8 independent key/block pairs for each cipher','公开单分组答案及每种密码 8 对独立密钥 / 分组')),(t('SM2 signature','SM2 签名'),t('Historical-draft known answer with its explicitly different test curve; current curve bidirectional OpenSSL verification','使用明确不同历史测试曲线的草案已知答案；当前曲线与 OpenSSL 双向验签')),(t('SM2 encryption','SM2 加密'),t('OpenSSL encrypt ↔ reference decrypt and the reverse, with explicit raw/DER conversion','OpenSSL 加密 ↔ 参考解密及反向，明确 raw / DER 转换')),(t('Failure paths','失败路径'),t('Wrong message/ID, bad points, zero r, tampered C2/C3, forbidden scalar and oversize ID','错误消息 / ID、坏点、零 r、篡改 C2 / C3、禁止标量与超长 ID')),(t('Exchange','交换'),t('A/B shared key and confirmation equality; changed identity changes derived key','A / B 共享密钥及确认相同，改变身份改变派生密钥'))])+p(t('Independent checks used OpenSSL 3.6.2. If the CLI is absent, the two independent test methods are explicitly skipped; the known-answer tests still run. If an installed OpenSSL lacks an algorithm, the independent test fails rather than pretending success. Exchange is algebraically cross-checked between sides; it is not independently certified or a network protocol test.','独立检查使用 OpenSSL 3.6.2。若缺少 CLI，两个独立测试方法会明确跳过，已知答案测试仍运行。安装的 OpenSSL 若缺少算法，独立测试会失败而不假装成功。交换按双方算术结果互检，不是独立认证或网络协议测试。')),('sm2-draft','sm3-draft','sm4-draft','aes','openssl-sm2'))
        add('exercise','Inspect exact outputs before changing the implementation','改变实现前检查精确输出','A small intentional change should break the relevant known answer.','小的刻意修改应使对应已知答案失配。',p(t('Try changing SM3’s final XOR to addition or its P1 rotation; inspect why abc fails. Change SM4’s L′ into L and observe the first round-key mismatch. Swap the SM2 signature ID and see verification reject. Compare the same scalar multiple on SM2 and P-256; the points differ because the domains differ. Restore the original code and rerun the checks.','可将 SM3 最终异或改成加法或改变 P1 旋转，观察 abc 为何失败；将 SM4 的 L′ 换成 L，观察首轮密钥失配；更换 SM2 签名 ID，观察验签拒绝；比较 SM2 与 P-256 相同标量倍点，结果因域不同而不同。恢复原码后重跑检查。'),t('Read rejection tests as security properties, not just exceptions to silence. A complete production deployment would additionally need side-channel evaluation, protocol interoperability and assurance appropriate to its application.','应将拒绝测试读成安全属性，而不是需要消除的异常。完整生产部署还需侧信道评估、协议互操作及适合应用的保障。')),('nist-kex','gmssl'))
    return rows
